   213		const callTool = async (name: string, args: ToolArgs) => {
   214			if (!app) {
   215				if (!isEmbedded) {
   216					console.log("[mcp-app] tools/call", name, args);
   217					setLastResult((last) => ({
   218						isError: false,
   219						seq: (last?.seq ?? 0) + 1,
   220					}));
   221				}
   222				return;
   223			}
