   239				}
   240				setLastResult((last) => ({
   241					isError: result.isError === true,
   242					seq: (last?.seq ?? 0) + 1,
   243				}));
   244			} catch {
   245				setLastResult((last) => ({
   246					isError: true,
   247					seq: (last?.seq ?? 0) + 1,
   248				}));
   249			}
   250		};
