    13	function isStructuredObject(value: unknown): value is UnknownRecord {
    14		return Boolean(value) && typeof value === "object" && !Array.isArray(value);
    15	}
    16	
    17	export function approvalCapabilityFromMeta(meta: unknown): string | null {
    18		if (!isStructuredObject(meta)) return null;
    19		const token = meta["lobu/approval-capability"];
    20		return typeof token === "string" && token.length <= 4_096 ? token : null;
    21	}
    22	
    23	function approvalCapabilityFromResult(result: unknown): string | null {
    24		if (!isStructuredObject(result)) return null;
    25		return approvalCapabilityFromMeta(result._meta);
    26	}
    27	
    28	function dataFromToolOutput<T>(toolOutput: unknown): T | null {
    29		if (!isStructuredObject(toolOutput)) return null;
    30		if (Object.hasOwn(toolOutput, "structuredContent")) {
    31			return isStructuredObject(toolOutput.structuredContent)
    32				? (toolOutput.structuredContent as T)
    33				: null;
    34		}
    35		return toolOutput as T;
    36	}
    37	
    38	function dataFromWidgetState<T>(widgetState: unknown): T | null | undefined {
    39		if (!isStructuredObject(widgetState)) return undefined;
    40		const privateContent = widgetState.privateContent;
    41		if (!isStructuredObject(privateContent)) return undefined;
    42		const snapshot = privateContent[LOBU_VIEW_SNAPSHOT_KEY];
    43		if (!isStructuredObject(snapshot)) return undefined;
    44		if (snapshot.version !== LOBU_VIEW_SNAPSHOT_VERSION) return undefined;
    45		return snapshot.data === null
    46			? null
    47			: isStructuredObject(snapshot.data)
    48				? (snapshot.data as T)
    49				: undefined;
    50	}
    51	
    52	function displaySafeSnapshotData<T>(data: T | null): T | null {
    53		if (!isStructuredObject(data) || !Array.isArray(data.actions)) return data;
    54		return {
    55			...data,
    56			actions: data.actions.filter(
    57				(action) =>
    58					!isStructuredObject(action) || action.tool !== "resolve_lobu_approval",
    59			),
    60		} as T;
    61	}
    62	
    63	/**
    64	 * Cache the latest server-authored view in ChatGPT's per-widget UI state. The
    65	 * snapshot is a display-only reload fallback; a fresh tool result always wins.
    66	 * Hidden result metadata is deliberately excluded.
    67	 */
    68	export function persistOpenAiViewSnapshot<T>(
    69		globals: unknown,
    70		data: T | null,
    71	): boolean {
    72		if (!isStructuredObject(globals)) return false;
    73		const setWidgetState = globals.setWidgetState;
    74		if (typeof setWidgetState !== "function") return false;
    75	
    76		const widgetState = isStructuredObject(globals.widgetState)
    77			? globals.widgetState
    78			: {};
    79		const privateContent = isStructuredObject(widgetState.privateContent)
    80			? widgetState.privateContent
    81			: {};
    82		const nextWidgetState = {
    83			...widgetState,
    84			privateContent: {
    85				...privateContent,
    86				[LOBU_VIEW_SNAPSHOT_KEY]: {
    87					version: LOBU_VIEW_SNAPSHOT_VERSION,
    88					data: displaySafeSnapshotData(data),
    89				},
    90			},
    91		};
    92	
    93		try {
    94			const result = Reflect.apply(setWidgetState, globals, [nextWidgetState]);
    95			if (isStructuredObject(result) && typeof result.catch === "function") {
    96				void Reflect.apply(result.catch, result, [() => {}]);
    97			}
    98			return true;
    99		} catch {
   100			return false;
   101		}
   102	}
   103	
   104	/**
   105	 * Read ChatGPT's compatibility globals without making them a dependency of the
   106	 * portable MCP Apps bridge. ChatGPT restores these globals for historical
   107	 * cards, including after the standard tool-result notification has already
   108	 * happened in an earlier page lifetime.
   109	 */
   110	export function readOpenAiCompatSnapshot<T>(
   111		globals: unknown,
   112	): OpenAiCompatSnapshot<T> {
   113		if (!isStructuredObject(globals)) {
   114			return { data: undefined, approvalCapability: undefined };
   115		}
   116	
   117		const hasToolOutput = Object.hasOwn(globals, "toolOutput");
   118		const data = hasToolOutput
   119			? dataFromToolOutput<T>(globals.toolOutput)
   120			: dataFromWidgetState<T>(globals.widgetState);
   121		const hasToolResponseMetadata = Object.hasOwn(
   122			globals,
   123			"toolResponseMetadata",
   124		);
   125		const metadata = isStructuredObject(globals.toolResponseMetadata)
   126			? globals.toolResponseMetadata
   127			: null;
   128		const approvalCapability = hasToolResponseMetadata
   129			? metadata
   130				? (approvalCapabilityFromResult(metadata.mcp_tool_result) ??
   131					approvalCapabilityFromResult(metadata.call_tool_result))
   132				: null
   133			: undefined;
   134	
   135		return { data, approvalCapability };
   136	}
