    20	function approvalCapabilityFromResult(result: unknown): string | null {
    21		if (!isStructuredObject(result)) return null;
    22		return approvalCapabilityFromMeta(result._meta);
    23	}
    24	
    25	/**
    26	 * Read ChatGPT's compatibility globals without making them a dependency of the
    27	 * portable MCP Apps bridge. ChatGPT restores these globals for historical
    28	 * cards, including after the standard tool-result notification has already
    29	 * happened in an earlier page lifetime.
    30	 */
    31	export function readOpenAiCompatSnapshot<T>(
    32		globals: unknown,
    33	): OpenAiCompatSnapshot<T> {
    34		if (!isStructuredObject(globals)) {
    35			return { data: undefined, approvalCapability: undefined };
    36		}
    37	
    38		const hasToolOutput = Object.hasOwn(globals, "toolOutput");
    39		const data = hasToolOutput
    40			? isStructuredObject(globals.toolOutput)
    41				? (globals.toolOutput as T)
    42				: null
    43			: undefined;
    44		const hasToolResponseMetadata = Object.hasOwn(
    45			globals,
    46			"toolResponseMetadata",
    47		);
    48		const metadata = isStructuredObject(globals.toolResponseMetadata)
    49			? globals.toolResponseMetadata
    50			: null;
    51		const approvalCapability = hasToolResponseMetadata
    52			? metadata
    53				? (approvalCapabilityFromResult(metadata.mcp_tool_result) ??
    54					approvalCapabilityFromResult(metadata.call_tool_result))
    55				: null
    56			: undefined;
    57	
    58		return { data, approvalCapability };
