   508	  const status = row.interaction_status ?? 'pending';
   509	  const baseTitle = displayValue(row.title ?? `Approval run ${runId}`, TITLE_MAX_LENGTH).replace(
   510	    /\s+—\s+pending approval$/i,
   511	    ''
   512	  );
   513	  const actions: LobuView['actions'] = [];
