   515	    const { ownerSlug, baseUrl } = await getOrgUrlContext(ctx);
   516	    const href = buildResourcePermalink(ownerSlug, { kind: 'run', runId }, baseUrl);
   517	    if (!href || href.length > ACTION_HREF_MAX_LENGTH || !/^https?:\/\//i.test(href)) {
   518	      throw new ToolUserError('The Lobu review link is unavailable for this workspace.', 500);
